scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var hits = new global.EcsPortability(new global.EcsAst(engine.rootNode)).emails();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CFG-003',
        title: 'Hardcoded email address',
        recommendation: 'Send to users or groups, or read addresses from a system property or a notification recipient list, so they can differ per environment and change without a code change.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
